const queryClient=new QueryClient({defaultOptions:{queries:{staleTime:60000,gcTime:10*60*1000,retry:1,refetchOnWindowFocus:false}}})

function AdminNavSync(){
  const location=useLocation()
  useEffect(()=>{
    const aside=document.querySelector('.admin>aside')
    if(!aside)return
    aside.querySelector('.admin-primary-nav')?.remove()
    const nav=document.createElement('nav');nav.className='admin-primary-nav'
    const links=[['/admin','Tableau de bord'],['/admin/catalogue','Catalogue'],['/admin/operations?section=bookings','Réservations'],['/admin/operations?section=payments','Paiements'],['/admin/operations?section=clients','Utilisateurs'],['/admin/marketing','Promotions'],['/admin/voitures','Voitures']]
    const current=`${location.pathname}${location.search}`
    for(const [href,label] of links){const link=document.createElement('a');link.href=href;link.textContent=label;if(current===href||(href==='/admin'&&location.pathname==='/admin'))link.className='active';nav.append(link)}
    const marker=Array.from(aside.children).find(child=>child.tagName==='P')
    marker?.after(nav)
    let logout=null
    if(location.pathname!=='/admin/catalogue'){logout=document.createElement('button');logout.type='button';logout.className='admin-logout';logout.textContent='Déconnexion';logout.addEventListener('click',()=>{localStorage.removeItem('helmi_user');localStorage.removeItem('helmi_token');localStorage.removeItem('helmi_refresh_token');queryClient.clear();window.location.assign('/connexion')});aside.append(logout)}
    const originalButtons=Array.from(aside.children).filter(child=>child.tagName==='BUTTON')
    const body=document.querySelector('.admin-body')
    let contextNav=null,observer=null
    if(body&&originalButtons.length){
      contextNav=document.createElement('nav');contextNav.className='admin-context-nav';contextNav.dataset.page=location.pathname;contextNav.dataset.section=new URLSearchParams(location.search).get('section')||'';contextNav.setAttribute('aria-label','Sous-sections')
      const sync=()=>Array.from(contextNav.children).forEach((button,index)=>button.classList.toggle('active',originalButtons[index]?.classList.contains('active')))
      originalButtons.forEach(original=>{const button=document.createElement('button');button.type='button';button.textContent=original.textContent.trim();button.addEventListener('click',()=>{original.click();sync()});contextNav.append(button)})
      body.prepend(contextNav);sync();observer=new MutationObserver(sync);originalButtons.forEach(button=>observer.observe(button,{attributes:true,attributeFilter:['class']}))
    }
    return()=>{observer?.disconnect();contextNav?.remove();logout?.remove();nav.remove()}
  },[location.pathname,location.search])
  return null
}

function AdminRentalPortal(){
  const location=useLocation();const [target,setTarget]=useState(null);const [visible,setVisible]=useState(false)
  useEffect(()=>{if(location.pathname!=='/admin/voitures'){setTarget(null);return}const body=document.querySelector('.admin-cars-page'),tabs=document.querySelector('.admin-context-nav');setTarget(body);const sync=()=>setVisible(Array.from(tabs?.querySelectorAll('button')||[]).some(button=>button.classList.contains('active')&&button.textContent.includes('Locations')));sync();if(!tabs)return;const observer=new MutationObserver(sync);observer.observe(tabs,{subtree:true,attributes:true,attributeFilter:['class']});return()=>observer.disconnect()},[location.pathname])
  return target&&visible?createPortal(<AdminRentalForm/>,target):null
}

function AdminRentalForm(){
  const [form,setForm]=useState({});const clients=useQuery({queryKey:['rental-clients'],queryFn:()=>operationsApi.users('client')});const cars=useQuery({queryKey:['rental-cars'],queryFn:carApi.adminCars})
  const create=useMutation({mutationFn:carApi.book,onSuccess:()=>{toast.success('Location créée pour le client');setForm({});queryClient.invalidateQueries({queryKey:['admin-car-rentals']});queryClient.invalidateQueries({queryKey:['admin-dashboard']})},onError:e=>toast.error(e.response?.data?.message||'Création impossible')})
  const submit=e=>{e.preventDefault();create.mutate({...form,userId:Number(form.userId),carId:Number(form.carId)})}
  return <section className="panel admin-rental-create"><div className="panel-head"><div><h3>Nouvelle location</h3><p>Réservez un véhicule au nom d’un client.</p></div></div><form onSubmit={submit}><label>Client<select required value={form.userId||''} onChange={e=>setForm({...form,userId:e.target.value})}><option value="">Choisir un client</option>{(clients.data||[]).map(x=><option key={x.id} value={x.id}>{x.prenom} {x.nom} — {x.email}</option>)}</select></label><label>Véhicule<select required value={form.carId||''} onChange={e=>setForm({...form,carId:e.target.value})}><option value="">Choisir un véhicule</option>{(cars.data||[]).map(x=><option key={x.id} value={x.id}>{x.marque} {x.modele} — {Number(x.prix_jour)} DT/jour</option>)}</select></label><label>Début<input required type="date" value={form.date_debut||''} onChange={e=>setForm({...form,date_debut:e.target.value})}/></label><label>Fin<input required type="date" min={form.date_debut} value={form.date_fin||''} onChange={e=>setForm({...form,date_fin:e.target.value})}/></label><label>Conducteur<input required value={form.conducteur_nom||''} onChange={e=>setForm({...form,conducteur_nom:e.target.value})}/></label><label>CIN / Passeport / Permis<input required value={form.conducteur_document||''} onChange={e=>setForm({...form,conducteur_document:e.target.value})}/></label><label>Téléphone<input required value={form.telephone||''} onChange={e=>setForm({...form,telephone:e.target.value})}/></label><button disabled={create.isPending} className="btn btn-gold">{create.isPending?'Création…':'Créer la location'}</button></form></section>
}

function AdminProfileModal(){
  const {user,setUser}=useApp();const location=useLocation();const [open,setOpen]=useState(false);const [form,setForm]=useState({});const [photoFile,setPhotoFile]=useState(null);const [preview,setPreview]=useState('')
  const photoUrl=value=>value?.startsWith('http')?value:value?`${api.defaults.baseURL.replace(/\/api$/,'')}${value}`:''
  useEffect(()=>{if(!location.pathname.startsWith('/admin'))return;const trigger=document.querySelector('.admin-user');if(!trigger)return;const avatar=trigger.firstElementChild;if(user?.photo){avatar.style.backgroundImage=`url("${photoUrl(user.photo)}")`;avatar.style.backgroundSize='cover';avatar.style.backgroundPosition='center';avatar.textContent=''}const show=()=>{setForm({prenom:user?.prenom||'',nom:user?.nom||'',telephone:user?.telephone||''});setPhotoFile(null);setPreview('');setOpen(true)};trigger.setAttribute('role','button');trigger.setAttribute('tabindex','0');trigger.setAttribute('aria-label','Modifier mon profil');trigger.addEventListener('click',show);const key=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}};trigger.addEventListener('keydown',key);return()=>{trigger.removeEventListener('click',show);trigger.removeEventListener('keydown',key)}},[location.pathname,user?.id,user?.photo])
  useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview)},[preview])
  const update=useMutation({mutationFn:async()=>{const profile=await userApi.update(form);if(!photoFile)return profile;const photo=await userApi.photo(photoFile);return {...profile,...photo}},onSuccess:data=>{setUser({...user,...data});toast.success('Profil et photo mis à jour');setOpen(false)},onError:e=>toast.error(e.response?.data?.message||'Modification impossible')})
  if(!open)return null
  return <div className="profile-modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setOpen(false)}><section className="profile-modal" role="dialog" aria-modal="true" aria-labelledby="admin-profile-title"><div className="panel-head"><div><span className="kicker dark">COMPTE ADMINISTRATEUR</span><h2 id="admin-profile-title">Modifier mon profil</h2></div><button aria-label="Fermer" onClick={()=>setOpen(false)}><X/></button></div><div className="profile-modal-avatar">{(preview||user?.photo)?<img src={preview||photoUrl(user.photo)} alt="Photo de profil"/>:<>{form.prenom?.[0]}{form.nom?.[0]}</>}</div><label className="profile-photo-picker"><span>Changer la photo</span><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>{const file=e.target.files?.[0];if(!file)return;setPhotoFile(file);setPreview(URL.createObjectURL(file))}}/><small>JPG, PNG ou WebP — 5 Mo maximum</small></label><p className="profile-modal-email">{user?.email}</p><form onSubmit={e=>{e.preventDefault();update.mutate()}}><label>Prénom<input required value={form.prenom||''} onChange={e=>setForm({...form,prenom:e.target.value})}/></label><label>Nom<input required value={form.nom||''} onChange={e=>setForm({...form,nom:e.target.value})}/></label><label>Téléphone<input type="tel" value={form.telephone||''} onChange={e=>setForm({...form,telephone:e.target.value})}/></label><div><button type="button" className="btn btn-outline" onClick={()=>setOpen(false)}>Annuler</button><button disabled={update.isPending} className="btn btn-gold">{update.isPending?'Enregistrement…':'Enregistrer'}</button></div></form></section></div>
}

class AppErrorBoundary extends React.Component {
  constructor(props){super(props);this.state={error:null}}
  static getDerivedStateFromError(error){return {error}}
  componentDidCatch(error,info){console.error('Erreur de rendu Helmi Travel',error,info)}
  resetSession=()=>{
    localStorage.removeItem('helmi_user')
    localStorage.removeItem('helmi_token')
    localStorage.removeItem('helmi_refresh_token')
    window.location.assign('/connexion')
  }
  render(){
    if(!this.state.error)return this.props.children
    return <main className="app-crash"><section><h1>La page n’a pas pu s’afficher</h1><p>Une donnée de session ou une réponse du serveur a provoqué une erreur inattendue.</p><details><summary>Détail technique</summary><code>{this.state.error.message}</code></details><div><button className="btn btn-gold" onClick={()=>window.location.reload()}>Réessayer</button><button className="btn btn-outline" onClick={this.resetSession}>Réinitialiser la connexion</button></div></section></main>
  }
}

function AppProvider({children}) {
  const [favorites, setFavorites] = useState([])
  const [user, setUserState] = useState(()=>{try{return JSON.parse(localStorage.getItem('helmi_user'))}catch{return null}})
  useEffect(()=>{if(user&&localStorage.getItem('helmi_token'))userApi.favorites().then(rows=>setFavorites(rows.map(x=>`${x.type}-${x.item_id}`))).catch(()=>{});else setFavorites([])},[user?.id])
  const setUser=user=>{setUserState(user);if(user)localStorage.setItem('helmi_user',JSON.stringify(user));else{const refresh=localStorage.getItem('helmi_refresh_token');if(refresh)authApi.logout(refresh).catch(()=>{});localStorage.removeItem('helmi_user');localStorage.removeItem('helmi_token');localStorage.removeItem('helmi_refresh_token');queryClient.clear()}}
  const toggleFavorite = async id =>{if(!user){toast.info('Connectez-vous pour ajouter des favoris');return}const [type,itemId]=String(id).split('-');const removing=favorites.includes(id);setFavorites(v=>removing?v.filter(x=>x!==id):[...v,id]);try{if(removing){const rows=await userApi.favorites();const row=rows.find(x=>x.type===type&&x.item_id===Number(itemId));if(row)await userApi.removeFavorite(row.id)}else await userApi.addFavorite(type,Number(itemId));queryClient.invalidateQueries({queryKey:['my-favorites']})}catch{setFavorites(v=>removing?[...v,id]:v.filter(x=>x!==id));toast.error('Impossible de modifier ce favori')}}
  return <AppContext.Provider value={{favorites, toggleFavorite, user, setUser}}><AdminNavSync/><AdminRentalPortal/><AdminProfileModal/><AnalyticsConsent/>{children}</AppContext.Provider>
}

